function renderProjects(){
 const active=projectStatus(state),task=active?.project.decisions[active.progress.choices.length-1]?.options.find(o=>o.id===active.progress.choices.at(-1)),completed=state.projects.completed,available=PROJECTS.find(p=>!completed.some(c=>c.id===p.id)&&p.unlock<=state.totalSeconds),next=PROJECTS.find(p=>!completed.some(c=>c.id===p.id));
 hidden('projects-entry',state.totalSeconds<PROJECTS[0].unlock&&!active&&!completed.length);text('project-summary',active?`${active.project.name} · ${active.phase==='decision'?'A decision is ready':`Building ${task?.label.toLowerCase()??'a feature'} · ${waitLabel(active.remaining)} left`}`:available?`${available.name} · Ready to start`:next?`${completed.length} completed · Next project in ${waitLabel(Math.max(0,next.unlock-state.totalSeconds))}`:`All ${PROJECTS.length} projects made. Your collection is complete.`);text('projects-open',active?.phase==='decision'?'Make a decision ↗':'Open projects ↗');$('projects-open').classList.toggle('ready',active?.phase==='decision');hidden('project-collection',!completed.length);for(const p of PROJECTS)hidden(`keepsake-${p.id}`,!completed.some(c=>c.id===p.id));
}
function updateProjects(all:boolean){
 const active=projectStatus(state),done=state.projects.completed,next=PROJECTS.find(p=>p.unlock>state.totalSeconds&&!done.some(c=>c.id===p.id));
 for(const p of PROJECTS){
  const completed=done.find(c=>c.id===p.id),current=active?.project.id===p.id,unlocked=p.unlock<=state.totalSeconds,choices=current?active.progress.choices:completed?.choices??[];
  row(`project-${p.id}`,all||current||!!completed||unlocked||p===next,current,current?0:completed?3:unlocked?1:2);
  text(`project-${p.id}-state`,completed?'Completed · reward active':current?active.phase==='decision'?`Choose feature ${choices.length+1} of 2`:`Building feature ${choices.length} of 2`:unlocked?`${money(p.cost)} to start · two 2 minute builds`:`Available in ${waitLabel(p.unlock-state.totalSeconds)} of play · ${money(p.cost)} to start`);
  const start=document.querySelector<HTMLButtonElement>(`[data-action="project-start"][data-id="${p.id}"]`)!;start.hidden=current||!!completed;updateButton('project-start',p.id,!unlocked?'Locked':active?'Finish current project':`Start · ${money(p.cost)}`,!unlocked||!!active||!!completed||state.cash<p.cost);
  const building=current&&active.phase==='building';hidden(`project-${p.id}-build`,!building);if(building){text(`project-${p.id}-task`,`Building feature ${choices.length} of 2`);text(`project-${p.id}-countdown`,`${Math.ceil(active.remaining)}s`);width(`project-${p.id}-progress`,(1-active.remaining/120)*100);}
  for(let i=0;i<p.decisions.length;i++)hidden(`project-${p.id}-decision-${i}`,!current||active.phase!=='decision'||i!==choices.length);
  const built=choices.length-(building?1:0);hidden(`project-${p.id}-feedback`,built===0);for(let i=0;i<2;i++){const choice=i<built?p.decisions[i]?.options.find(o=>o.id===choices[i]):undefined;hidden(`project-${p.id}-feature-${i}`,!choice);hidden(`project-${p.id}-response-${i}`,!choice);if(choice){text(`project-${p.id}-feature-${i}`,choice.feature);text(`project-${p.id}-response-${i}`,choice.feedback);}}
 }
}
